/*
 * A119408  Decimal equivalent of the binary string generated by the n X n
 *          identity matrix.
 * https://oeis.org/A119408
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = Sum_{k=0}^{n-1} 2^{(n+1)*k} (geometric series)
 *            Equivalent: a(n) = (2^{n(n+1)} - 1)/(2^{n+1} - 1)
 * Range:     u8 n <= 2, u16 n <= 4, u32 n <= 5, u64 n <= 8, u128 n <= 11,
 *            big any n
 * Helpers:   pow2, seq_one
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/pow2.h"
#include "../utils/seq_one.h"

seq_t a(idx_t n) {
    if (n == 0) return seq_one();          /* undefined for n=0; return 1 as placeholder */
    seq_t r = pow2((idx_t)(n + 1));        /* r = 2^(n+1) */
    seq_t sum = seq_one();                /* first term (k = 0) */
    seq_t term = seq_one();

    for (idx_t i = 1; i < n; ++i) {
        term *= r;                        /* term = 2^(k*(n+1)) for next k */
        sum += term;
    }

    return sum;
}
